public class Task08CursorDiagnostic{public static void main(String[]args)throws Exception{try(var c=Task08MigrationProbe.source().getConnection()){System.out.println(Task08MigrationProbe.query(c,"SELECT o.id,o.reconcile_scan_seq,o.state,o.next_check_at,o.reconcile_expires_at,UTC_TIMESTAMP(6) AS now,t.task_type,t.state AS task_state,e.state AS execution_state FROM external_operation o JOIN external_execution e ON e.operation_id=o.id AND e.execution_no=o.current_execution_no JOIN durable_task t ON t.id=e.task_id ORDER BY o.reconcile_scan_seq DESC LIMIT 20"));System.out.println(Task08MigrationProbe.query(c,"SELECT COUNT(*) AS operations FROM external_operation"));}}}